import{_ as e,c as t,o as l,aj as o}from"./chunks/framework.CDhdelVI.js";const g=JSON.parse('{"title":"Scalds","description":"Learn how to use tangzhong and yudane in the KitchenRatio calculator for softer crumb, moisture retention, and dough handling control.","frontmatter":{"title":"Scalds","description":"Learn how to use tangzhong and yudane in the KitchenRatio calculator for softer crumb, moisture retention, and dough handling control.","head":[["meta",{"name":"description","content":"Learn how to use tangzhong and yudane in the KitchenRatio calculator for softer crumb, moisture retention, and dough handling control."}],["meta",{"property":"og:title","content":"Scalds"}],["meta",{"property":"og:description","content":"Learn how to use tangzhong and yudane in the KitchenRatio calculator for softer crumb, moisture retention, and dough handling control."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/scalds.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Scalds"}],["meta",{"name":"twitter:description","content":"Learn how to use tangzhong and yudane in the KitchenRatio calculator for softer crumb, moisture retention, and dough handling control."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/scalds.html"}]]},"headers":[],"relativePath":"guides/scalds.md","filePath":"guides/scalds.md"}'),i={name:"guides/scalds.md"};function n(r,a,s,d,h,c){return l(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="scalds" tabindex="-1">Scalds <a class="header-anchor" href="#scalds" aria-label="Permalink to “Scalds”">​</a></h1><p>Scalds are a texture control move: pre-gelatinize flour with hot water before final mixing. They are how you steer crumb softness, chew, and moisture retention with intent instead of guesswork.</p><div class="guide-glance"><div class="guide-glance-card"><strong>Best For</strong><span>Choosing a scald method when softness, chew, or shelf life needs to change.</span></div><div class="guide-glance-card"><strong>Focus</strong><span>Tangzhong, yudane, allocation ranges, and how each one shifts dough feel.</span></div><div class="guide-glance-card"><strong>Read This Next</strong><span>Hydration and preferments if you are combining multiple advanced dough tools.</span></div></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Always let scalds cool before they touch yeast. Hot scald can damage yeast activity and weaken fermentation.</p></div><p>In the KitchenRatio calculator, scalds live in <strong>Advanced → Scalds</strong>.</p><h2 id="types-in-the-calculator" tabindex="-1">Types in the Calculator <a class="header-anchor" href="#types-in-the-calculator" aria-label="Permalink to “Types in the Calculator”">​</a></h2><ul><li><strong>Tangzhong</strong><br> Cooked flour paste built for softness and shelf life.</li><li><strong>Yudane</strong><br> Boiling-water scald that pushes chew and moisture retention.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The calculator allows only one scald type at a time: tangzhong or yudane.</p></div><h2 id="quick-choice" tabindex="-1">Quick Choice <a class="header-anchor" href="#quick-choice" aria-label="Permalink to “Quick Choice”">​</a></h2><ul><li><strong>Choose tangzhong</strong> when you want a softer, more pillowy crumb and longer-lasting tenderness.</li><li><strong>Choose yudane</strong> when you want more chew, more wheat presence, and stronger moisture retention.</li><li><strong>Choose a traditional grain scald</strong> when rye or whole-grain behavior is the real problem you are trying to solve.</li></ul><h2 id="other-scald-style-not-in-calculator-yet" tabindex="-1">Other Scald Style (Not in Calculator Yet) <a class="header-anchor" href="#other-scald-style-not-in-calculator-yet" aria-label="Permalink to “Other Scald Style (Not in Calculator Yet)”">​</a></h2><h3 id="traditional-european-scandinavian-scald" tabindex="-1">Traditional European / Scandinavian Scald <a class="header-anchor" href="#traditional-european-scandinavian-scald" aria-label="Permalink to “Traditional European / Scandinavian Scald”">​</a></h3><p>This style is common in rye-heavy and mixed-grain baking, where hot water is used to hydrate and soften part of the flour (or meal) before final mixing. It is less about &quot;pillowy milk bread&quot; and more about flavor development, moisture control, and crumb stability in hearty loaves.</p><p>How it behaves:</p><ul><li>Hot water hydrates starches and changes how flour absorbs and holds water.</li><li>Often improves keeping quality and can support a more even crumb in dense dough systems.</li><li>Can also mellow sharp grain notes and build a deeper malt-like profile.</li></ul><p>Typical use in practice:</p><ul><li>Frequently used with rye flour, whole grain flour, or coarse meal components.</li><li>Can be made with plain hot water or paired with malt/syrup in some regional styles.</li><li>Usually prepared ahead of final mixing and cooled before yeast is introduced.</li></ul><h2 id="deeper-breakdown" tabindex="-1">Deeper Breakdown <a class="header-anchor" href="#deeper-breakdown" aria-label="Permalink to “Deeper Breakdown”">​</a></h2><h3 id="tangzhong" tabindex="-1">Tangzhong <a class="header-anchor" href="#tangzhong" aria-label="Permalink to “Tangzhong”">​</a></h3><ul><li>Typically uses a higher water ratio and is heated into a smooth paste.</li><li>It helps dough stay soft and tender longer.</li><li>It often works best in sandwich loaves, rolls, and milk breads.</li><li>Push it too hard and dough can go gummy or too soft.</li></ul><h3 id="yudane" tabindex="-1">Yudane <a class="header-anchor" href="#yudane" aria-label="Permalink to “Yudane”">​</a></h3><ul><li>Usually built at lower water ratio with boiling water and rested.</li><li>It adds chew and usually tightens dough feel versus tangzhong.</li><li>It is useful when you want structure plus moisture retention.</li><li>If under-rested or under-hydrated, it stays lumpy and fights your mix.</li></ul><h3 id="traditional-european-scandinavian-scald-1" tabindex="-1">Traditional European / Scandinavian Scald <a class="header-anchor" href="#traditional-european-scandinavian-scald-1" aria-label="Permalink to “Traditional European / Scandinavian Scald”">​</a></h3><ul><li>Often used with rye flour, whole grain flour, or coarse meal.</li><li>Focuses on grain hydration behavior, moisture retention, and flavor depth in robust loaves.</li><li>Usually less about ultra-soft crumb and more about stability and keeping quality.</li><li>Works best when cooled fully before yeast enters the system.</li></ul><h2 id="how-allocation-works" tabindex="-1">How Allocation Works <a class="header-anchor" href="#how-allocation-works" aria-label="Permalink to “How Allocation Works”">​</a></h2><p>Like preferments, scald flour and water are allocated from your existing formula. They are not extra add-ons.</p><ul><li><strong>Scald flour grams</strong> = total flour × flour allocation %</li><li><strong>Scald water grams</strong> = scald flour × water ratio</li></ul><p>You get live totals for:</p><ul><li>allocated flour and water</li><li>remaining main dough flour and water</li></ul><h2 id="tangzhong-settings" tabindex="-1">Tangzhong Settings <a class="header-anchor" href="#tangzhong-settings" aria-label="Permalink to “Tangzhong Settings”">​</a></h2><ul><li>Flour allocation: <strong>0 to 20%</strong> (default <strong>5%</strong>)</li><li>Water ratio: <strong>1.0 to 8.0</strong> (default <strong>1:5.0</strong> flour:water)</li></ul><h2 id="yudane-settings" tabindex="-1">Yudane Settings <a class="header-anchor" href="#yudane-settings" aria-label="Permalink to “Yudane Settings”">​</a></h2><ul><li>Flour allocation: <strong>0 to 25%</strong> (default <strong>10%</strong>)</li><li>Water ratio: <strong>0.8 to 1.5</strong> (default <strong>1:1.0</strong> flour:water)</li></ul><h2 id="how-to-make-tangzhong" tabindex="-1">How to Make Tangzhong <a class="header-anchor" href="#how-to-make-tangzhong" aria-label="Permalink to “How to Make Tangzhong”">​</a></h2><ol><li>Weigh flour and water using your target flour allocation and ratio.</li><li>Whisk together in a saucepan until no dry flour remains.</li><li>Heat over medium-low while stirring continuously.</li><li>Cook until it thickens into a smooth paste.</li><li>Remove from heat, cover surface, and cool before mixing final dough.</li></ol><p>Typical target texture:</p><ul><li>Thick pudding-like paste that holds brief lines from the whisk.</li></ul><p>Typical use:</p><ul><li>Mix fully cooled tangzhong into the final dough with the remaining ingredients.</li></ul><h2 id="how-to-make-yudane" tabindex="-1">How to Make Yudane <a class="header-anchor" href="#how-to-make-yudane" aria-label="Permalink to “How to Make Yudane”">​</a></h2><ol><li>Weigh flour and boiling water at your target ratio (often near 1:1).</li><li>Pour boiling water over flour and mix until evenly hydrated.</li><li>Cover and let it rest until fully cool and hydrated through.</li><li>Optionally refrigerate overnight for easier handling.</li><li>Tear into pieces and mix into final dough.</li></ol><p>Typical target texture:</p><ul><li>Firm, hydrated mass with no dry pockets.</li></ul><p>Typical use:</p><ul><li>Works well when added in chunks during initial mixing.</li></ul><h2 id="practical-workflow" tabindex="-1">Practical Workflow <a class="header-anchor" href="#practical-workflow" aria-label="Permalink to “Practical Workflow”">​</a></h2><ol><li>Build your base formula in the calculator.</li><li>Open <strong>Advanced → Scalds</strong>.</li><li>Enable tangzhong or yudane.</li><li>Set flour allocation and water ratio.</li><li>Prepare the scald using the displayed flour and water grams.</li><li>Mix final dough using remaining flour and water shown in Advanced.</li></ol><p>For traditional European/Scandinavian scald (not in calculator yet), run it manually:</p><ol><li>Choose the rye/whole-grain portion you want to scald.</li><li>Add hot water and mix thoroughly.</li><li>Rest covered until fully cooled and hydrated.</li><li>Add this scalded portion during final dough mixing.</li></ol><h2 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to “Practical Tips”">​</a></h2><ul><li>Start with tangzhong around 5% flour and 1:5 ratio for softer sandwich-style crumbs.</li><li>Start with yudane around 10% flour and 1:1 ratio for chewier texture.</li><li>For traditional rye-style scalds, start modest and observe dough behavior before increasing scalded flour share.</li><li>If dough feels tighter than expected, review <a href="/guides/hydration.html">Hydration</a> and adjust on purpose.</li><li>Keep total advanced allocation in range to avoid over-allocation warnings.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li><strong>Crumb feels gummy</strong><ul><li>Lower scald flour allocation.</li><li>Confirm bake is fully done before cooling.</li></ul></li><li><strong>Dough feels too tight</strong><ul><li>Reduce yudane allocation or raise final dough hydration slightly.</li><li>Increase rest time after mixing before shaping.</li></ul></li><li><strong>Scald does not blend smoothly</strong><ul><li>Break up lumps before final mixing.</li><li>Let the scald cool fully and hydrate evenly.</li></ul></li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/preferments.html">Preferments</a></li><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div>',57)])])}const m=e(i,[["render",n]]);export{g as __pageData,m as default};
